*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#a5d7d9;color:#fff;font-family:'DM Sans',sans-serif;touch-action:none}#game{position:relative;width:100%;height:100dvh;min-height:420px;overflow:hidden;background:linear-gradient(#a6d9db,#e7d9b2)}#world{display:block;width:100%;height:100%;outline:0}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(20,54,49,.31),transparent 25%,transparent 65%,rgba(16,45,38,.22)),radial-gradient(ellipse at center,transparent 46%,rgba(27,63,54,.16) 100%)}.topbar{position:absolute;z-index:3;top:max(22px,env(safe-area-inset-top));left:clamp(18px,4vw,58px);right:clamp(18px,4vw,58px);display:flex;align-items:flex-start;justify-content:space-between;gap:12px;pointer-events:none}.brand{display:flex;align-items:center;gap:11px;text-shadow:0 2px 10px #244d4566}.brand-seal{width:37px;height:37px;border:1px solid #fff9;border-radius:50%;display:grid;place-items:center;font-size:19px;color:#ffefb5;background:#294e3d66}.brand-name{font-family:Marcellus,serif;font-size:15px;letter-spacing:2.5px;font-weight:bold}.brand-sub{font-size:9px;letter-spacing:2.5px;opacity:.78;margin-top:3px}.quest-card,.status-card{color:#f9f4e3;background:rgba(28,57,48,.67);border:1px solid rgba(255,255,255,.2);box-shadow:0 8px 26px #18352d22;backdrop-filter:blur(12px);border-radius:8px}.quest-card{display:flex;align-items:center;gap:11px;padding:11px 15px;min-width:255px}.quest-icon{font-size:24px;color:#f5d477}.quest-kicker,.status-label{font-size:9px;letter-spacing:1.9px;opacity:.72;font-weight:700}.quest-card #quest-text{font-size:12px;font-weight:600;margin-top:3px}.shard-count{margin-left:auto;font-family:Marcellus,serif;font-size:23px;color:#ffdc75}.shard-count i{font-style:normal;font-size:12px;color:#ffffffa8}.status-card{text-align:right;padding:10px 14px;min-width:135px}.hearts{letter-spacing:3px;color:#f39a7e;font-size:17px;margin-top:1px;text-shadow:0 1px 5px #572f3566}.status-hint{font-size:9px;opacity:.72;margin-top:3px}.location{position:absolute;z-index:2;top:104px;left:clamp(20px,4vw,60px);display:flex;gap:9px;align-items:center;font-weight:700;letter-spacing:1.6px;font-size:9px;color:#fff;text-shadow:0 1px 5px #274a40}.location-dot{width:6px;height:6px;border-radius:50%;background:#ffe287;box-shadow:0 0 8px #fff3a9}.location-line{width:26px;height:1px;background:#ffffff88}.bottom-ui{position:absolute;z-index:3;left:clamp(18px,4vw,58px);right:clamp(18px,4vw,58px);bottom:max(21px,env(safe-area-inset-bottom));display:flex;justify-content:space-between;align-items:flex-end;pointer-events:none}.controls-hint{display:flex;align-items:center;gap:4px;padding:9px 11px;background:#2146389e;border:1px solid #ffffff36;border-radius:7px;backdrop-filter:blur(8px);color:#fff}.keycap{width:18px;height:18px;display:grid;place-items:center;border:1px solid #ffffff74;border-radius:4px;font-size:9px;font-weight:700;background:#ffffff16}.keycap.wide{width:44px;font-size:8px}.hint-copy{font-size:8px;letter-spacing:1.1px;margin:0 7px 0 3px;opacity:.85;font-weight:700}.hint-divider{height:17px;width:1px;background:#ffffff55;margin:0 7px}.corner-note{font-size:10px;letter-spacing:.5px;color:#fff;text-shadow:0 1px 5px #26493d;opacity:.86}.corner-note span{color:#ffe28c;margin-right:5px}.toast{position:absolute;left:50%;bottom:52px;transform:translate(-50%,10px);padding:10px 16px;border:1px solid #ffffff66;border-radius:30px;background:#264b3de8;font-size:12px;letter-spacing:.3px;opacity:0;transition:.3s;white-space:nowrap;box-shadow:0 8px 30px #19372940}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile-controls{display:none;pointer-events:auto}.intro-screen,.end-screen{position:absolute;z-index:5;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,rgba(15,42,37,.58),rgba(17,44,39,.2) 60%,rgba(17,44,39,.16));backdrop-filter:blur(2px);transition:opacity .55s,visibility .55s}.intro-screen.dismiss{opacity:0;visibility:hidden;pointer-events:none}.intro-card,.end-card{width:min(410px,calc(100% - 38px));margin-left:min(32vw,350px);padding:36px 39px 27px;background:rgba(21,51,43,.83);border:1px solid rgba(255,255,255,.26);box-shadow:0 18px 70px #112e2966;border-radius:4px 22px 4px 22px;backdrop-filter:blur(18px);text-align:left}.intro-emblem{font-size:26px;color:#f5d87e;margin-bottom:12px;text-shadow:0 0 22px #ffdb7d99}.eyebrow{font-size:9px;letter-spacing:2.5px;font-weight:700;color:#e7ce88}.intro-card h1,.end-card h2{font-family:Marcellus,serif;font-weight:400;font-size:48px;line-height:1.03;margin:12px 0 13px;color:#fff9e9;letter-spacing:-.7px}.intro-card h1 em,.end-card h2 em{font-weight:400;color:#f1d784}.intro-card p,.end-card p{color:#eff1ddc9;font-size:13px;line-height:1.65;margin:0 0 17px;max-width:320px}.intro-meta{display:flex;gap:15px;color:#e9dda9;font-size:8px;letter-spacing:1px;font-weight:700;margin-bottom:21px}.begin-btn{width:100%;height:45px;padding:0 15px;border:0;border-radius:3px;background:#e9cb78;color:#284638;font-family:'DM Sans',sans-serif;font-size:10px;letter-spacing:1.5px;font-weight:800;text-align:left;cursor:pointer;transition:background .2s,transform .2s}.begin-btn:hover{background:#f5df9b;transform:translateY(-1px)}.begin-btn span{float:right;font-size:17px;line-height:12px}.intro-foot{text-align:center;font-size:8px;letter-spacing:1px;color:#ffffff9a;margin-top:15px}.end-screen{background:rgba(17,45,38,.58)}.end-screen.hidden{display:none}.end-card{text-align:center;margin:0;padding:38px}.end-card h2{font-size:42px}.end-card .intro-emblem{font-size:34px}.end-card p{margin:0 auto 22px}.joystick{display:flex;align-items:center;flex-direction:column;gap:5px}.joy-ring{width:100px;height:100px;border-radius:50%;background:#183f3488;border:1px solid #ffffff70;display:grid;place-items:center;box-shadow:0 5px 20px #163c3255}.joy-knob{width:43px;height:43px;border-radius:50%;background:#ffffffa8;border:1px solid #fff;box-shadow:0 2px 10px #163c3240;transform:translate(0,0)}.joy-label{font-size:8px;letter-spacing:1.6px;text-shadow:0 1px 5px #163c32}.attack-btn{width:73px;height:73px;border-radius:50%;border:1px solid #ffe6a4;background:#e9ca76e8;color:#284638;box-shadow:0 5px 20px #163c3255;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:2px}.attack-btn span{font-size:26px}.attack-btn small{font-size:8px;letter-spacing:1px;font-weight:800}.attack-btn:active{transform:scale(.94)}
@media(max-width:700px){.topbar{top:max(12px,env(safe-area-inset-top));left:14px;right:14px;align-items:center;gap:7px}.brand{gap:7px}.brand-seal{width:30px;height:30px;font-size:16px}.brand-name{font-size:11px;letter-spacing:1.7px}.brand-sub{font-size:7px;letter-spacing:1.5px}.quest-card{min-width:0;padding:8px 9px;gap:6px;flex:1;max-width:185px}.quest-icon{font-size:17px}.quest-kicker{font-size:7px;letter-spacing:1.3px}.quest-card #quest-text{font-size:9px;max-width:100px;line-height:1.2}.shard-count{font-size:18px}.shard-count i{font-size:10px}.status-card{min-width:83px;padding:7px 8px}.status-label{font-size:7px;letter-spacing:1.3px}.hearts{font-size:13px;letter-spacing:1px}.status-hint{display:none}.location{top:64px;left:17px;font-size:8px}.bottom-ui{left:16px;right:16px;bottom:max(13px,env(safe-area-inset-bottom));align-items:flex-end}.controls-hint{display:none}.mobile-controls{display:flex;align-items:flex-end;justify-content:space-between;width:100%}.corner-note{display:none}.toast{bottom:112px;font-size:11px}.intro-screen{background:linear-gradient(180deg,rgba(14,42,38,.12),rgba(14,42,38,.48))}.intro-card{margin:12vh 0 0;width:min(380px,calc(100% - 34px));padding:27px 27px 20px}.intro-card h1{font-size:41px;margin:8px 0 10px}.intro-card p{font-size:12px;margin-bottom:12px}.intro-meta{gap:11px;margin-bottom:15px;font-size:7px}.begin-btn{height:42px}.intro-foot{font-size:7px;margin-top:12px}.end-card{margin:0;padding:28px 25px}.end-card h2{font-size:37px}}
@media(min-width:701px) and (max-height:650px){.intro-card{padding:24px 32px}.intro-card h1{font-size:39px;margin:7px 0}.intro-card p{margin-bottom:10px}.intro-meta{margin-bottom:12px}.intro-foot{margin-top:9px}}

import * as THREE from 'three';

const canvas=document.querySelector('#world');
const scene=new THREE.Scene();
scene.background=new THREE.Color('#a9d8d8');
scene.fog=new THREE.FogExp2('#a9d8d8',.0125);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,180);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.13;
scene.add(new THREE.HemisphereLight('#e6f8e9','#54684a',2.05));
const sun=new THREE.DirectionalLight('#fff0c8',3.1);sun.position.set(-25,40,22);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-45;sun.shadow.camera.right=45;sun.shadow.camera.top=45;sun.shadow.camera.bottom=-45;sun.shadow.bias=-.0002;scene.add(sun);
const mats={grass:new THREE.MeshStandardMaterial({color:'#78a85d',roughness:1}),grass2:new THREE.MeshStandardMaterial({color:'#8cb56a',roughness:1}),darkgrass:new THREE.MeshStandardMaterial({color:'#628b51',roughness:1}),water:new THREE.MeshStandardMaterial({color:'#70bac0',roughness:.36,metalness:.06}),sand:new THREE.MeshStandardMaterial({color:'#d9c58f',roughness:1}),stone:new THREE.MeshStandardMaterial({color:'#958f78',roughness:1}),bark:new THREE.MeshStandardMaterial({color:'#79573a',roughness:1}),leaf:new THREE.MeshStandardMaterial({color:'#497d50',roughness:1}),leaf2:new THREE.MeshStandardMaterial({color:'#659456',roughness:1}),gold:new THREE.MeshStandardMaterial({color:'#efc75f',metalness:.35,roughness:.36,emissive:'#6d4a0b',emissiveIntensity:.3}),crystal:new THREE.MeshStandardMaterial({color:'#9af4ed',metalness:.2,roughness:.18,emissive:'#3bd5cc',emissiveIntensity:1.8}),white:new THREE.MeshStandardMaterial({color:'#fff4d5',roughness:.55}),blue:new THREE.MeshStandardMaterial({color:'#4c8fbb',roughness:.55}),red:new THREE.MeshStandardMaterial({color:'#db8267',roughness:.7}),enemy:new THREE.MeshStandardMaterial({color:'#745c9c',roughness:.5,emissive:'#37214d',emissiveIntensity:.3})};
function mesh(geo,mat,parent=scene,x=0,y=0,z=0){const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function group(parent=scene,x=0,y=0,z=0){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);return g}
function box(parent,mat,x,y,z,sx,sy,sz){return mesh(new THREE.BoxGeometry(sx,sy,sz),mat,parent,x,y,z)}
function cylinder(parent,mat,x,y,z,rt,rb,h,n=8){return mesh(new THREE.CylinderGeometry(rt,rb,h,n),mat,parent,x,y,z)}
function sphere(parent,mat,x,y,z,r,detail=1){return mesh(new THREE.IcosahedronGeometry(r,detail),mat,parent,x,y,z)}
function randSeed(seed){let s=seed;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296}}
const random=randSeed(22);

// A little island, ringed with warm stone and shallow water.
const water=mesh(new THREE.CircleGeometry(80,80),mats.water,scene,0,-1.7,0);water.rotation.x=-Math.PI/2;water.receiveShadow=false;
const ground=mesh(new THREE.CylinderGeometry(33,35,3.8,64,1),mats.grass,scene,0,-.3,0);ground.receiveShadow=true;
const sandRing=mesh(new THREE.CylinderGeometry(34,36,1.35,64),mats.sand,scene,0,-1.45,0);
const underside=mesh(new THREE.CylinderGeometry(31,35,3,64),mats.stone,scene,0,-3.35,0);
const top=mesh(new THREE.CircleGeometry(33,64),mats.grass,scene,0,1.62,0);top.rotation.x=-Math.PI/2;top.receiveShadow=true;
// Soft paths winding through the grove.
const pathMat=new THREE.MeshStandardMaterial({color:'#c7b37f',roughness:1});
function path(points,width){const curve=new THREE.CatmullRomCurve3(points.map(([x,z])=>new THREE.Vector3(x,1.65,z)));const pts=curve.getPoints(90);for(let i=0;i<pts.length-1;i++){const a=pts[i],b=pts[i+1],d=a.distanceTo(b);const strip=mesh(new THREE.BoxGeometry(width,.025,d+width*.22),pathMat,scene,(a.x+b.x)/2,1.655,(a.z+b.z)/2);strip.rotation.y=-Math.atan2(b.z-a.z,b.x-a.x)+Math.PI/2;strip.receiveShadow=false}}
path([[0,1],[0,7],[-2,12],[-7,16],[-10,20]],2.15);
path([[0,7],[6,10],[11,8],[16,5]],1.35);
path([[-2,12],[-11,10],[-16,4],[-20,0]],1.4);
path([[0,7],[5,1],[9,-4],[14,-9]],1.35);
// Glades of stylized low-poly trees.
function tree(x,z,scale=1){const g=group(scene,x,1.6,z);g.scale.setScalar(scale);cylinder(g,mats.bark,0,.92,0,.28,.4,1.85,7);sphere(g,mats.leaf,0,2.1,0,1.13,1);const crown=sphere(g,mats.leaf2,-.48,2.35,.18,.72,1);crown.rotation.z=.2;sphere(g,mats.leaf,.48,2.5,-.06,.79,1);sphere(g,mats.leaf2,.06,2.95,0,.65,1);return g}
const treeSpots=[[-9,-5],[-13,-8],[-18,-5],[-23,-10],[-25,-2],[-19,15],[-23,20],[-14,23],[-7,24],[4,23],[12,21],[21,17],[24,11],[23,1],[22,-7],[19,-16],[11,-19],[4,-23],[-8,-22],[-17,-18],[-28,8],[28,8],[27,-14],[-4,19],[15,15],[-14,-13],[24,-3],[3,-17]];
treeSpots.forEach(([x,z],i)=>tree(x,z,.78+(i%4)*.12));
// Shrine at the heart of the island.
const shrine=group(scene,-10,1.67,20);const shrineStone=new THREE.MeshStandardMaterial({color:'#d7ccaa',roughness:.9});
box(shrine,shrineStone,0,.35,0,5.6,.65,4.2);box(shrine,shrineStone,0,1.9,-1.35,4.2,2.8,.4);box(shrine,shrineStone,0,1.8,1.38,4.2,2.5,.4);box(shrine,shrineStone,-1.95,1.65,0,.42,2.5,2.4);box(shrine,shrineStone,1.95,1.65,0,.42,2.5,2.4);box(shrine,mats.gold,0,3.38,0,5.1,.38,4);box(shrine,shrineStone,0,3.72,0,4.5,.35,3.5);
cylinder(shrine,mats.gold,0,.95,.25,.78,.85,.16,8);
const shrineCore=sphere(shrine,mats.crystal,0,1.9,.25,.56,1);
const arch=group(shrine,0,0,-1.75);cylinder(arch,shrineStone,-1.3,2.55,0,.2,.24,2.4,6);cylinder(arch,shrineStone,1.3,2.55,0,.2,.24,2.4,6);box(arch,mats.gold,0,3.78,0,3.1,.32,.5);
// Stone accents and flower clumps.
for(let i=0;i<78;i++){const a=random()*Math.PI*2,r=8+random()*21,x=Math.cos(a)*r,z=Math.sin(a)*r;if(x*x+(z-20)*(z-20)<45)continue;const rock=sphere(scene,mats.stone,x,1.72,z,.25+random()*.35,0);rock.scale.set(1.3,.65,.9);rock.rotation.y=random()*6}
const flowerMats=['#f1d57d','#e9a5a1','#f5eee0'].map(c=>new THREE.MeshStandardMaterial({color:c,roughness:.8}));
for(let i=0;i<120;i++){const a=random()*Math.PI*2,r=4+random()*27,x=Math.cos(a)*r,z=Math.sin(a)*r;if(x*x+(z-20)*(z-20)<60)continue;for(let j=0;j<3;j++){const f=sphere(scene,flowerMats[(i+j)%3],x+(random()-.5)*.4,1.88,z+(random()-.5)*.4,.09,0);f.scale.y=1.4}}

// The little wanderer.
const player=group(scene,0,1.66,1);
const skin=new THREE.MeshStandardMaterial({color:'#edc49a',roughness:.72});
const tunic=new THREE.MeshStandardMaterial({color:'#477f7a',roughness:.65});
const cape=new THREE.MeshStandardMaterial({color:'#d47c56',roughness:.8});
const belt=new THREE.MeshStandardMaterial({color:'#e4c378',roughness:.65});
cylinder(player,tunic,0,.78,0,.43,.48,.9,7);sphere(player,tunic,0,1.12,0,.44,1);
const head=sphere(player,skin,0,1.63,-.03,.37,1);head.scale.set(.86,1,.85);
const hat=mesh(new THREE.ConeGeometry(.42,.85,5),mats.blue,player,0,2.1,-.03);hat.rotation.z=-.12;
box(player,cape,0,.85,.39,.62,.7,.13);box(player,belt,0,.53,0,.83,.11,.84);
for(const side of [-1,1]){const arm=cylinder(player,tunic,side*.48,.86,0,.14,.17,.65,6);arm.rotation.z=side*-.24;const leg=cylinder(player,mats.blue,side*.2,.2,0,.16,.17,.43,6);leg.rotation.z=side*.09; sphere(player,skin,side*.14,1.68,.29,.045,1)}
// Three sunshards tucked into distinct corners of the grove.
const shards=[];
function makeShard(x,z,id){const g=group(scene,x,1.78,z);const pedestal=cylinder(g,mats.stone,0,.12,0,.55,.63,.24,7);pedestal.rotation.y=.3;
const crystal=mesh(new THREE.OctahedronGeometry(.66,0),mats.crystal,g,0,.93,0);crystal.scale.set(.72,1.35,.72);crystal.rotation.y=.25;const halo=mesh(new THREE.TorusGeometry(.8,.035,6,36),mats.gold,g,0,.84,0);halo.rotation.x=Math.PI/2;
const light=new THREE.PointLight('#77fff0',2.2,5);light.position.set(0,1.1,0);g.add(light);g.userData={id,crystal,halo,light,baseY:1.78,found:false};shards.push(g)}
makeShard(16,5,0);makeShard(-20,0,1);makeShard(11,-17,2);
// Shadowy grove wisps: curious, not too fierce.
const enemies=[];
function makeWisp(x,z){const g=group(scene,x,1.7,z);sphere(g,mats.enemy,0,.52,0,.72,1);const belly=sphere(g,new THREE.MeshStandardMaterial({color:'#bea4d0',roughness:.45,emissive:'#5d3980',emissiveIntensity:.3}),0,.18,0,.46,1);belly.scale.y=.57;
for(const side of [-1,1]){sphere(g,mats.white,side*.22,.68,.57,.11,1);sphere(g,new THREE.MeshBasicMaterial({color:'#40304c'}),side*.22,.68,.66,.05,1)}
const spike=mesh(new THREE.ConeGeometry(.18,.42,5),mats.enemy,g,0,1.18,-.15);spike.rotation.z=.3;const glow=new THREE.PointLight('#b59bff',.7,3);glow.position.y=.6;g.add(glow);g.userData={hp:2,alive:true,phase:Math.random()*7,hit:0,home:new THREE.Vector3(x,1.7,z)};enemies.push(g)}
makeWisp(5,-5);makeWisp(-17,-9);makeWisp(19,-10);
// Controls: keyboard on desktop, draggable virtual stick + strike on touch.
const keys=new Set();let stick={x:0,y:0};let attacking=0;let attackCooldown=0;let health=3;let found=0;let started=false;let won=false;let invulnerable=0;let toastTimer=0;
const joy=document.querySelector('#joystick'),knob=document.querySelector('#joy-knob');let joyPointer=null;
const isTouch=()=>matchMedia('(pointer:coarse)').matches||innerWidth<760;
function setJoy(e){const r=joy.querySelector('.joy-ring').getBoundingClientRect();const dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=34,m=Math.min(1,max/Math.max(1,len));stick.x=dx*m/max;stick.y=dy*m/max;knob.style.transform=`translate(${dx*m}px,${dy*m}px)`}
joy.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joy.setPointerCapture(joyPointer);setJoy(e)});joy.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)setJoy(e)});function resetJoy(){joyPointer=null;stick={x:0,y:0};knob.style.transform='translate(0,0)'}joy.addEventListener('pointerup',resetJoy);joy.addEventListener('pointercancel',resetJoy);
document.querySelector('#attack').addEventListener('pointerdown',e=>{e.preventDefault();strike()});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if(e.key===' '||e.key==='j'||e.key==='J')strike();if(e.key==='Enter'&&!started)begin()});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
function begin(){if(started)return;started=true;document.querySelector('#intro').classList.add('dismiss');toast('The grove is yours to explore.');}
document.querySelector('#begin').addEventListener('click',begin);document.querySelector('#play-again').addEventListener('click',()=>{document.querySelector('#end-screen').classList.add('hidden');started=true;won=false;toast('Take your time. The grove is at peace.')});
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=2.7}
function strike(){if(!started||attackCooldown>0)return;attacking=.28;attackCooldown=.58;player.userData.swing=.38;let target=null,best=3.25;
for(const e of enemies){if(!e.userData.alive)continue;const d=player.position.distanceTo(e.position);if(d<best){best=d;target=e}}
if(target){target.userData.hp--;target.userData.hit=.27;target.position.add(new THREE.Vector3(player.position.x-target.position.x,0,player.position.z-target.position.z).normalize().multiplyScalar(-.65));if(target.userData.hp<=0){target.userData.alive=false;scene.remove(target);toast('A grove wisp drifts away.');document.querySelector('#status-hint').textContent='The air feels lighter.'}else toast('A clean hit! Keep going.')}else toast('Your blade cuts through the air.');}
const heartsEl=document.querySelector('#hearts');function updateHearts(){heartsEl.textContent='♥ '.repeat(health)+'♡ '.repeat(3-health);heartsEl.setAttribute('aria-label',`${health} of 3 hearts`)}

const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const clock=new THREE.Clock();let elapsed=0;
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);elapsed+=dt;
// Move relative to the angled camera, with soft acceleration and island bounds.
let ix=0,iz=0;if(keys.has('w')||keys.has('arrowup'))iz-=1;if(keys.has('s')||keys.has('arrowdown'))iz+=1;if(keys.has('a')||keys.has('arrowleft'))ix-=1;if(keys.has('d')||keys.has('arrowright'))ix+=1;
