// Directions mapped to screen-forward and screen-right in the world camera.
const camDir=new THREE.Vector3(.0,0,1);const right=new THREE.Vector3(1,0,0);const moveX=right.x*ix+camDir.x*iz,moveZ=right.z*ix+camDir.z*iz;
if(started){const speed=5.1;player.position.x+=moveX*speed*dt;player.position.z+=moveZ*speed*dt;const radius=Math.hypot(player.position.x,player.position.z);if(radius>31.5){player.position.x*=31.5/radius;player.position.z*=31.5/radius}
if(il>.08){player.rotation.y=Math.atan2(moveX,moveZ);player.userData.walk=(player.userData.walk||0)+dt*12;player.position.y=1.66+Math.abs(Math.sin(player.userData.walk))*.07}else player.position.y=1.66;
}
attackCooldown=Math.max(0,attackCooldown-dt);attacking=Math.max(0,attacking-dt);invulnerable=Math.max(0,invulnerable-dt);if(player.userData.swing){player.userData.swing-=dt;const arm=player.children[6];if(arm)arm.rotation.x=Math.sin(player.userData.swing*22)*.9}
player.visible=invulnerable<=0||Math.floor(elapsed*12)%2===0;
// Shards shimmer, and quietly draw the eye.
for(const s of shards){if(s.userData.found)continue;const phase=elapsed*2.1+s.userData.id*2.2;s.position.y=s.userData.baseY+Math.sin(phase)*.14;s.userData.crystal.rotation.y=phase*.55;s.userData.halo.rotation.z=phase*.3;s.userData.light.intensity=2+Math.sin(phase*1.7)*.55;if(started&&player.position.distanceTo(s.position)<1.55){s.userData.found=true;scene.remove(s);found++;document.querySelector('#shard-count').textContent=found;document.querySelector('#status-hint').textContent=found===3?'The shrine is waking…':'A sunshard found!';toast(found===3?'All three gathered! Return to the shrine.':`Sunshard gathered · ${found} of 3`);if(found===3)document.querySelector('#quest-text').textContent='Return the light to the shrine';}}
