import * as THREE from 'three';
const canvas=document.querySelector('#world');
const scene=new THREE.Scene();scene.background=new THREE.Color('#a9d8d8');scene.fog=new THREE.FogExp2('#a9d8d8',.0125);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,180);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.13;
scene.add(new THREE.HemisphereLight('#e6f8e9','#54684a',2.05));const sun=new THREE.DirectionalLight('#fff0c8',3.1);sun.position.set(-25,40,22);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-45;sun.shadow.camera.right=45;sun.shadow.camera.top=45;sun.shadow.camera.bottom=-45;sun.shadow.bias=-.0002;scene.add(sun);
const mats={grass:new THREE.MeshStandardMaterial({color:'#78a85d',roughness:1}),grass2:new THREE.MeshStandardMaterial({color:'#8cb56a',roughness:1}),darkgrass:new THREE.MeshStandardMaterial({color:'#628b51',roughness:1}),water:new THREE.MeshStandardMaterial({color:'#70bac0',roughness:.36,metalness:.06}),sand:new THREE.MeshStandardMaterial({color:'#d9c58f',roughness:1}),stone:new THREE.MeshStandardMaterial({color:'#958f78',roughness:1}),bark:new THREE.MeshStandardMaterial({color:'#79573a',roughness:1}),leaf:new THREE.MeshStandardMaterial({color:'#497d50',roughness:1}),leaf2:new THREE.MeshStandardMaterial({color:'#659456',roughness:1}),gold:new THREE.MeshStandardMaterial({color:'#efc75f',metalness:.35,roughness:.36,emissive:'#6d4a0b',emissiveIntensity:.3}),crystal:new THREE.MeshStandardMaterial({color:'#9af4ed',metalness:.2,roughness:.18,emissive:'#3bd5cc',emissiveIntensity:1.8}),white:new THREE.MeshStandardMaterial({color:'#fff4d5',roughness:.55}),blue:new THREE.MeshStandardMaterial({color:'#4c8fbb',roughness:.55}),red:new THREE.MeshStandardMaterial({color:'#db8267',roughness:.7}),enemy:new THREE.MeshStandardMaterial({color:'#745c9c',roughness:.5,emissive:'#37214d',emissiveIntensity:.3})};
function mesh(geo,mat,parent=scene,x=0,y=0,z=0){const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function group(parent=scene,x=0,y=0,z=0){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);return g}
function box(parent,mat,x,y,z,sx,sy,sz){return mesh(new THREE.BoxGeometry(sx,sy,sz),mat,parent,x,y,z)}
function cylinder(parent,mat,x,y,z,rt,rb,h,n=8){return mesh(new THREE.CylinderGeometry(rt,rb,h,n),mat,parent,x,y,z)}
function sphere(parent,mat,x,y,z,r,detail=1){return mesh(new THREE.IcosahedronGeometry(r,detail),mat,parent,x,y,z)}
function randSeed(seed){let s=seed;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296}}
const random=randSeed(22);
// A little island, ringed with warm stone and shallow water.
const water=mesh(new THREE.CircleGeometry(80,80),mats.water,scene,0,-1.7,0);water.rotation.x=-Math.PI/2;water.receiveShadow=false;
const ground=mesh(new THREE.CylinderGeometry(33,35,3.8,64,1),mats.grass,scene,0,-.3,0);ground.receiveShadow=true;
const sandRing=mesh(new THREE.CylinderGeometry(34,36,1.35,64),mats.sand,scene,0,-1.45,0);
const underside=mesh(new THREE.CylinderGeometry(31,35,3,64),mats.stone,scene,0,-3.35,0);
const top=mesh(new THREE.CircleGeometry(33,64),mats.grass,scene,0,1.62,0);top.rotation.x=-Math.PI/2;top.receiveShadow=true;
const pathMat=new THREE.MeshStandardMaterial({color:'#c7b37f',roughness:1});
function path(points,width){const curve=new THREE.CatmullRomCurve3(points.map(([x,z])=>new THREE.Vector3(x,1.65,z)));const pts=curve.getPoints(90);for(let i=0;i<pts.length-1;i++){const a=pts[i],b=pts[i+1],d=a.distanceTo(b);const strip=mesh(new THREE.BoxGeometry(width,.025,d+width*.22),pathMat,scene,(a.x+b.x)/2,1.655,(a.z+b.z)/2);strip.rotation.y=-Math.atan2(b.z-a.z,b.x-a.x)+Math.PI/2;strip.receiveShadow=false}}
path([[0,1],[0,7],[-2,12],[-7,16],[-10,20]],2.15);path([[0,7],[6,10],[11,8],[16,5]],1.35);path([[-2,12],[-11,10],[-16,4],[-20,0]],1.4);path([[0,7],[5,1],[9,-4],[14,-9]],1.35);
function tree(x,z,scale=1){const g=group(scene,x,1.6,z);g.scale.setScalar(scale);cylinder(g,mats.bark,0,.92,0,.28,.4,1.85,7);sphere(g,mats.leaf,0,2.1,0,1.13,1);const crown=sphere(g,mats.leaf2,-.48,2.35,.18,.72,1);crown.rotation.z=.2;sphere(g,mats.leaf,.48,2.5,-.06,.79,1);sphere(g,mats.leaf2,.06,2.95,0,.65,1);return g}
const treeSpots=[[-9,-5],[-13,-8],[-18,-5],[-23,-10],[-25,-2],[-19,15],[-23,20],[-14,23],[-7,24],[4,23],[12,21],[21,17],[24,11],[23,1],[22,-7],[19,-16],[11,-19],[4,-23],[-8,-22],[-17,-18],[-28,8],[28,8],[27,-14],[-4,19],[15,15],[-14,-13],[24,-3],[3,-17]];treeSpots.forEach(([x,z],i)=>tree(x,z,.78+(i%4)*.12));
// Shrine at the heart of the island.
const shrine=group(scene,-10,1.67,20);const shrineStone=new THREE.MeshStandardMaterial({color:'#d7ccaa',roughness:.9});
box(shrine,shrineStone,0,.35,0,5.6,.65,4.2);box(shrine,shrineStone,0,1.9,-1.35,4.2,2.8,.4);box(shrine,shrineStone,0,1.8,1.38,4.2,2.5,.4);box(shrine,shrineStone,-1.95,1.65,0,.42,2.5,2.4);box(shrine,shrineStone,1.95,1.65,0,.42,2.5,2.4);box(shrine,mats.gold,0,3.38,0,5.1,.38,4);box(shrine,shrineStone,0,3.72,0,4.5,.35,3.5);cylinder(shrine,mats.gold,0,.95,.25,.78,.85,.16,8);
const shrineCore=sphere(shrine,mats.crystal,0,1.9,.25,.56,1);const arch=group(shrine,0,0,-1.75);cylinder(arch,shrineStone,-1.3,2.55,0,.2,.24,2.4,6);cylinder(arch,shrineStone,1.3,2.55,0,.2,.24,2.4,6);box(arch,mats.gold,0,3.78,0,3.1,.32,.5);
for(let i=0;i<78;i++){const a=random()*Math.PI*2,r=8+random()*21,x=Math.cos(a)*r,z=Math.sin(a)*r;if(x*x+(z-20)*(z-20)<45)continue;const rock=sphere(scene,mats.stone,x,1.72,z,.25+random()*.35,0);rock.scale.set(1.3,.65,.9);rock.rotation.y=random()*6}
const flowerMats=['#f1d57d','#e9a5a1','#f5eee0'].map(c=>new THREE.MeshStandardMaterial({color:c,roughness:.8}));for(let i=0;i<120;i++){const a=random()*Math.PI*2,r=4+random()*27,x=Math.cos(a)*r,z=Math.sin(a)*r;if(x*x+(z-20)*(z-20)<60)continue;for(let j=0;j<3;j++){const f=sphere(scene,flowerMats[(i+j)%3],x+(random()-.5)*.4,1.88,z+(random()-.5)*.4,.09,0);f.scale.y=1.4}}
// The little wanderer.

