// The little wanderer.
const player=group(scene,0,1.66,1);
const skin=new THREE.MeshStandardMaterial({color:'#edc49a',roughness:.72}),tunic=new THREE.MeshStandardMaterial({color:'#477f7a',roughness:.65}),cape=new THREE.MeshStandardMaterial({color:'#d47c56',roughness:.8}),belt=new THREE.MeshStandardMaterial({color:'#e4c378',roughness:.65});
cylinder(player,tunic,0,.78,0,.43,.48,.9,7);sphere(player,tunic,0,1.12,0,.44,1);const head=sphere(player,skin,0,1.63,-.03,.37,1);head.scale.set(.86,1,.85);const hat=mesh(new THREE.ConeGeometry(.42,.85,5),mats.blue,player,0,2.1,-.03);hat.rotation.z=-.12;box(player,cape,0,.85,.39,.62,.7,.13);box(player,belt,0,.53,0,.83,.11,.84);
for(const side of [-1,1]){const arm=cylinder(player,tunic,side*.48,.86,0,.14,.17,.65,6);arm.rotation.z=side*-.24;cylinder(player,mats.blue,side*.2,.2,0,.16,.17,.43,6);sphere(player,skin,side*.14,1.68,.29,.045,1)}
// Three sunshards tucked into distinct corners of the grove.
const shards=[];
function makeShard(x,z,id){const g=group(scene,x,1.78,z);cylinder(g,mats.stone,0,.12,0,.55,.63,.24,7);const crystal=mesh(new THREE.OctahedronGeometry(.66,0),mats.crystal,g,0,.93,0);crystal.scale.set(.72,1.35,.72);crystal.rotation.y=.25;const halo=mesh(new THREE.TorusGeometry(.8,.035,6,36),mats.gold,g,0,.84,0);halo.rotation.x=Math.PI/2;const light=new THREE.PointLight('#77fff0',2.2,5);light.position.set(0,1.1,0);g.add(light);g.userData={id,crystal,halo,light,baseY:1.78,found:false};shards.push(g)}
makeShard(16,5,0);makeShard(-20,0,1);makeShard(11,-17,2);
// Shadowy grove wisps: curious, not too fierce.
const enemies=[];
function makeWisp(x,z){const g=group(scene,x,1.7,z);sphere(g,mats.enemy,0,.52,0,.72,1);const belly=sphere(g,new THREE.MeshStandardMaterial({color:'#bea4d0',roughness:.45,emissive:'#5d3980',emissiveIntensity:.3}),0,.18,0,.46,1);belly.scale.y=.57;for(const side of [-1,1]){sphere(g,mats.white,side*.22,.68,.57,.11,1);sphere(g,new THREE.MeshBasicMaterial({color:'#40304c'}),side*.22,.68,.66,.05,1)}mesh(new THREE.ConeGeometry(.18,.42,5),mats.enemy,g,0,1.18,-.15).rotation.z=.3;const glow=new THREE.PointLight('#b59bff',.7,3);glow.position.y=.6;g.add(glow);g.userData={hp:2,alive:true,phase:Math.random()*7,hit:0,home:new THREE.Vector3(x,1.7,z)};enemies.push(g)}
makeWisp(5,-5);makeWisp(-17,-9);makeWisp(19,-10);
// Controls: keyboard on desktop, draggable virtual stick + strike on touch.
const keys=new Set();let stick={x:0,y:0};let attacking=0,attackCooldown=0,health=3,found=0,started=false,won=false,invulnerable=0,toastTimer=0;
const joy=document.querySelector('#joystick'),knob=document.querySelector('#joy-knob');let joyPointer=null;
function setJoy(e){const r=joy.querySelector('.joy-ring').getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=34,m=Math.min(1,max/Math.max(1,len));stick.x=dx*m/max;stick.y=dy*m/max;knob.style.transform=`translate(${dx*m}px,${dy*m}px)`}
joy.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joy.setPointerCapture(joyPointer);setJoy(e)});joy.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)setJoy(e)});function resetJoy(){joyPointer=null;stick={x:0,y:0};knob.style.transform='translate(0,0)'}joy.addEventListener('pointerup',resetJoy);joy.addEventListener('pointercancel',resetJoy);document.querySelector('#attack').addEventListener('pointerdown',e=>{e.preventDefault();strike()});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());if(e.key===' '||e.key==='j'||e.key==='J')strike();if(e.key==='Enter'&&!started)begin()});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
function begin(){if(started)return;started=true;document.querySelector('#intro').classList.add('dismiss');toast('The grove is yours to explore.')}document.querySelector('#begin').addEventListener('click',begin);document.querySelector('#play-again').addEventListener('click',()=>{document.querySelector('#end-screen').classList.add('hidden');started=true;won=false;toast('Take your time. The grove is at peace.')});
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=2.7}
function strike(){if(!started||attackCooldown>0)return;attacking=.28;attackCooldown=.58;player.userData.swing=.38;let target=null,best=3.25;for(const e of enemies){if(!e.userData.alive)continue;const d=player.position.distanceTo(e.position);if(d<best){best=d;target=e}}if(target){target.userData.hp--;target.userData.hit=.27;target.position.add(new THREE.Vector3(player.position.x-target.position.x,0,player.position.z-target.position.z).normalize().multiplyScalar(-.65));if(target.userData.hp<=0){target.userData.alive=false;scene.remove(target);toast('A grove wisp drifts away.');document.querySelector('#status-hint').textContent='The air feels lighter.'}else toast('A clean hit! Keep going.')}else toast('Your blade cuts through the air.')}
const heartsEl=document.querySelector('#hearts');function updateHearts(){heartsEl.textContent='♥ '.repeat(health)+'♡ '.repeat(3-health);heartsEl.setAttribute('aria-label',`${health} of 3 hearts`)}

