const heartsEl=document.querySelector('#hearts');function updateHearts(){heartsEl.textContent='♥ '.repeat(health)+'♡ '.repeat(3-health);heartsEl.setAttribute('aria-label',`${health} of 3 hearts`)}
const clock=new THREE.Clock();let elapsed=0;const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);elapsed+=dt;
let ix=0,iz=0;if(keys.has('w')||keys.has('arrowup'))iz-=1;if(keys.has('s')||keys.has('arrowdown'))iz+=1;if(keys.has('a')||keys.has('arrowleft'))ix-=1;if(keys.has('d')||keys.has('arrowright'))ix+=1;if(Math.abs(stick.x)+Math.abs(stick.y)>.05){ix=stick.x;iz=stick.y}const il=Math.hypot(ix,iz);if(il>1){ix/=il;iz/=il}
// Directions mapped to screen-forward and screen-right in the world camera.
const camDir=new THREE.Vector3(0,0,1),right=new THREE.Vector3(1,0,0),moveX=right.x*ix+camDir.x*iz,moveZ=right.z*ix+camDir.z*iz;
if(started){const speed=5.1;player.position.x+=moveX*speed*dt;player.position.z+=moveZ*speed*dt;const radius=Math.hypot(player.position.x,player.position.z);if(radius>31.5){player.position.x*=31.5/radius;player.position.z*=31.5/radius}if(il>.08){player.rotation.y=Math.atan2(moveX,moveZ);player.userData.walk=(player.userData.walk||0)+dt*12;player.position.y=1.66+Math.abs(Math.sin(player.userData.walk))*.07}else player.position.y=1.66}
attackCooldown=Math.max(0,attackCooldown-dt);attacking=Math.max(0,attacking-dt);invulnerable=Math.max(0,invulnerable-dt);if(player.userData.swing){player.userData.swing-=dt;const arm=player.children[6];if(arm)arm.rotation.x=Math.sin(player.userData.swing*22)*.9}player.visible=invulnerable<=0||Math.floor(elapsed*12)%2===0;
for(const s of shards){if(s.userData.found)continue;const phase=elapsed*2.1+s.userData.id*2.2;s.position.y=s.userData.baseY+Math.sin(phase)*.14;s.userData.crystal.rotation.y=phase*.55;s.userData.halo.rotation.z=phase*.3;s.userData.light.intensity=2+Math.sin(phase*1.7)*.55;if(started&&player.position.distanceTo(s.position)<1.55){s.userData.found=true;scene.remove(s);found++;document.querySelector('#shard-count').textContent=found;document.querySelector('#status-hint').textContent=found===3?'The shrine is waking…':'A sunshard found!';toast(found===3?'All three gathered! Return to the shrine.':`Sunshard gathered · ${found} of 3`);if(found===3)document.querySelector('#quest-text').textContent='Return the light to the shrine'}}
for(const e of enemies){if(!e.userData.alive)continue;const u=e.userData;u.phase+=dt*2;const target=new THREE.Vector3(u.home.x+Math.sin(u.phase*.62)*1.5,1.7+Math.sin(u.phase*1.5)*.11,u.home.z+Math.cos(u.phase*.6)*1.5);if(started&&player.position.distanceTo(e.position)<7)target.lerp(player.position,.24);e.position.lerp(target,dt*.7);e.rotation.y=Math.sin(u.phase)*.24;if(u.hit>0){u.hit-=dt;e.scale.setScalar(1+Math.sin(u.hit*35)*.12)}else e.scale.lerp(new THREE.Vector3(1,1,1),dt*8);if(started&&invulnerable<=0&&player.position.distanceTo(e.position)<1.15){health=Math.max(0,health-1);updateHearts();invulnerable=1.4;player.position.x+=(player.position.x-e.position.x)*.8;player.position.z+=(player.position.z-e.position.z)*.8;toast(health?'A wisp bumps you. Watch your step.':'The grove is giving you another chance…');if(health===0){health=3;updateHearts();player.position.set(0,1.66,1);toast('The shrine returns you to safety.')}}}
if(found===3&&!won&&player.position.distanceTo(new THREE.Vector3(-10,1.66,20))<5){won=true;document.querySelector('#quest-text').textContent='The grove is restored';document.querySelector('#status-hint').textContent='A new path is opening…';shrineCore.material=mats.gold;shrineCore.scale.setScalar(1.45);shrineCore.material.emissiveIntensity=2;document.querySelector('#end-screen').classList.remove('hidden')}
const cameraTarget=new THREE.Vector3(player.position.x,player.position.y+7.5,player.position.z+10.5);camera.position.lerp(cameraTarget,1-Math.pow(.001,dt));camera.lookAt(player.position.x,1.4,player.position.z-1.6);shrineCore.rotation.y+=dt*.35;shrineCore.material.emissiveIntensity=found===3?2:1.15+Math.sin(elapsed*2)*.28;renderer.render(scene,camera);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.querySelector('#toast').classList.remove('show')}}
function resize(){camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<700?48:42;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight)}window.addEventListener('resize',resize);setTimeout(()=>document.querySelector('#loading').classList.add('gone'),700);updateHearts();animate();

